// Package build writes a brand package's generated files: tokens.css,
// brand.css, both DaisyUI theme forms, lint.json and the README brand sheet.
package build

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"sort"
	"strings"
	"text/template"

	"github.com/shermanhuman/brandkit/internal/brand"
	"github.com/shermanhuman/brandkit/internal/dtcg"
	"github.com/shermanhuman/brandkit/internal/lint"
)

// Options control a build.
type Options struct {
	// Images renders the README's PNG specimens with headless Chrome.
	// Without it the PNGs already on disk are kept (and must exist).
	Images bool
	Chrome string
}

// File is one generated file.
type File struct {
	Path string // relative to the brand package, slash-separated
	Data []byte
}

// Generate builds every text output in memory (no PNGs).
func Generate(b *brand.Brand) ([]File, error) {
	var files []File
	add := func(rel string, data []byte, err error) error {
		if err != nil {
			return fmt.Errorf("%s: %w", rel, err)
		}
		files = append(files, File{Path: rel, Data: data})
		return nil
	}
	out := func(rel string) string { return pathJoin(b.Config.Out, rel) }
	tok, err := TokensCSS(b)
	if err := add(out(b.Config.TokensCSS.File), tok, err); err != nil {
		return nil, err
	}
	bc, err := BrandCSS(b)
	if err := add(out(b.Config.BrandCSS.File), bc, err); err != nil {
		return nil, err
	}
	plain, err := DaisyThemes(b, "hex")
	if err := add(out(b.Config.DaisyUI.ThemesCSS), plain, err); err != nil {
		return nil, err
	}
	plugin, err := DaisyPlugin(b, "hex")
	if err := add(out(b.Config.DaisyUI.PluginCSS), plugin, err); err != nil {
		return nil, err
	}
	lj, err := LintConfig(b)
	if err := add(out(b.Config.Lint), lj, err); err != nil {
		return nil, err
	}
	sheet, err := Sheet(b)
	if err != nil {
		return nil, err
	}
	files = append(files, sheet...)
	return files, nil
}

// Write builds the package and writes its files, rendering specimens when
// opts.Images is set. It returns the paths written.
func Write(b *brand.Brand, opts Options) ([]string, error) {
	files, err := Generate(b)
	if err != nil {
		return nil, err
	}
	if opts.Images {
		imgs, err := Render(b, opts.Chrome)
		if err != nil {
			return nil, err
		}
		files = append(files, imgs...)
	} else {
		for _, p := range ImagePaths(b) {
			if _, err := os.Stat(filepath.Join(b.Dir, filepath.FromSlash(p))); err != nil {
				return nil, fmt.Errorf("%s is missing: build once with images (drop --no-images)", p)
			}
		}
	}
	var written []string
	keep := map[string]bool{}
	for _, p := range ImagePaths(b) {
		keep[p] = true
	}
	for _, f := range files {
		keep[f.Path] = true
	}
	// Drop sheet files brandkit wrote earlier and no longer makes, such as
	// the swatch of a colour that changed.
	sheetDir := filepath.Join(b.Dir, filepath.FromSlash(b.Config.Readme.Assets))
	if entries, err := os.ReadDir(sheetDir); err == nil {
		for _, e := range entries {
			rel := pathJoin(b.Config.Readme.Assets, e.Name())
			if e.Type().IsRegular() && sheetNameRe.MatchString(e.Name()) && !keep[rel] {
				if err := os.Remove(filepath.Join(sheetDir, e.Name())); err != nil {
					return nil, err
				}
				written = append(written, rel+" (removed)")
			}
		}
	}
	for _, f := range files {
		p := filepath.Join(b.Dir, filepath.FromSlash(f.Path))
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			return nil, err
		}
		if old, err := os.ReadFile(p); err == nil && bytes.Equal(old, f.Data) {
			continue
		}
		if err := os.WriteFile(p, f.Data, 0o644); err != nil {
			return nil, err
		}
		written = append(written, f.Path)
	}
	return written, nil
}

// sheetNameRe matches the names brandkit gives sheet files.
var sheetNameRe = regexp.MustCompile(`^(?:sw-[0-9a-f]{6,8}\.svg|(?:clearspace|scale)-[\w-]+\.svg|(?:type|components)-[\w-]+\.png)$`)

func pathJoin(a, b string) string {
	if a == "" || a == "." {
		return b
	}
	return strings.TrimSuffix(a, "/") + "/" + b
}

func generatedBy(b *brand.Brand) string {
	return fmt.Sprintf("Generated by brandkit from %s. Don't edit by hand.", b.Config.Resolver)
}

// ThemeDecls is one theme's declarations for a file.
type ThemeDecls struct {
	Name        string
	Label       string
	DaisyUI     string
	Selector    string
	ColorScheme string
	Default     bool
	// Decls holds every included token; Changed only those whose value
	// differs from the default theme's.
	Decls   []brand.Decl
	Changed []brand.Decl
	byName  map[string]brand.Decl
}

// TemplateData is what a tokens.css template receives.
type TemplateData struct {
	Brand       string
	GeneratedBy string
	Resolver    string
	Themes      []*ThemeDecls // the default first
	Default     *ThemeDecls
}

// Theme returns a theme's declarations by name (nil if none).
func (d *TemplateData) Theme(name string) *ThemeDecls {
	for _, t := range d.Themes {
		if t.Name == name {
			return t
		}
	}
	return nil
}

// Value returns the CSS value of a custom property (name without --).
func (t *ThemeDecls) Value(name string) (string, error) {
	d, ok := t.byName[name]
	if !ok {
		return "", fmt.Errorf("theme %s has no --%s", t.Name, name)
	}
	return d.Value, nil
}

func collect(b *brand.Brand, keep func(*dtcg.Token) bool) ([]*ThemeDecls, error) {
	var out []*ThemeDecls
	for _, th := range b.Themes {
		td := &ThemeDecls{Name: th.Name, Label: th.Config.Label, DaisyUI: th.Config.DaisyUI, Selector: th.Config.Selector,
			ColorScheme: th.Config.ColorScheme, Default: th.Config.Default, byName: map[string]brand.Decl{}}
		for _, t := range th.Tokens.List {
			if !keep(t) {
				continue
			}
			ds, err := brand.Decls(t, "hex")
			if err != nil {
				return nil, err
			}
			for _, d := range ds {
				if prev, dup := td.byName[d.Name]; dup && prev.Value != d.Value {
					return nil, fmt.Errorf("two tokens write --%s", d.Name)
				}
				td.byName[d.Name] = d
				td.Decls = append(td.Decls, d)
			}
		}
		out = append(out, td)
	}
	def := out[0]
	for _, td := range out {
		for _, d := range td.Decls {
			if dv, ok := def.byName[d.Name]; td == def || !ok || dv.Value != d.Value {
				td.Changed = append(td.Changed, d)
			}
		}
	}
	return out, nil
}

func inTokensCSS(b *brand.Brand) func(*dtcg.Token) bool {
	return func(t *dtcg.Token) bool { return brand.Matches(t, b.Config.TokensCSS.Include) }
}

// TokensCSS writes the legacy-compatible tokens file: the default layout,
// or the package's own template.
func TokensCSS(b *brand.Brand) ([]byte, error) {
	themes, err := collect(b, inTokensCSS(b))
	if err != nil {
		return nil, err
	}
	data := &TemplateData{Brand: b.Config.Name, GeneratedBy: generatedBy(b), Resolver: b.Config.Resolver, Themes: themes, Default: themes[0]}
	if tp := b.Config.TokensCSS.Template; tp != "" {
		src, err := os.ReadFile(filepath.Join(b.Dir, filepath.FromSlash(tp)))
		if err != nil {
			return nil, err
		}
		t, err := template.New(filepath.Base(tp)).Option("missingkey=error").Parse(string(src))
		if err != nil {
			return nil, err
		}
		var buf bytes.Buffer
		if err := t.Execute(&buf, data); err != nil {
			return nil, err
		}
		return buf.Bytes(), nil
	}
	header := b.Config.TokensCSS.Header
	if header == "" {
		header = b.Config.Name + " colours."
	}
	return writeBlocks(fmt.Sprintf("/* %s %s */\n", header, generatedBy(b)), themes, true), nil
}

// BrandCSS writes every token that isn't in tokens.css: type, spacing,
// radius, motion and the rest.
func BrandCSS(b *brand.Brand) ([]byte, error) {
	in := inTokensCSS(b)
	themes, err := collect(b, func(t *dtcg.Token) bool { return !in(t) })
	if err != nil {
		return nil, err
	}
	themes[0].Selector = ":root"
	return writeBlocks(fmt.Sprintf("/* %s type, spacing, radius and motion. %s */\n", b.Config.Name, generatedBy(b)), themes, false), nil
}

func writeBlocks(header string, themes []*ThemeDecls, scheme bool) []byte {
	var w bytes.Buffer
	w.WriteString(header)
	for i, td := range themes {
		decls := td.Changed
		if len(decls) == 0 && !(scheme && i > 0) {
			continue
		}
		w.WriteString("\n")
		w.WriteString(td.Selector + " {\n")
		for _, d := range decls {
			writeDecl(&w, d)
		}
		if scheme && td.ColorScheme != "" {
			fmt.Fprintf(&w, "  color-scheme: %s;\n", td.ColorScheme)
		}
		w.WriteString("}\n")
	}
	return w.Bytes()
}

func writeDecl(w *bytes.Buffer, d brand.Decl) {
	fmt.Fprintf(w, "  --%s: %s;", d.Name, d.Value)
	if d.Comment != "" {
		fmt.Fprintf(w, "   /* %s */", d.Comment)
	}
	w.WriteString("\n")
}

// DaisyRoles are the colour variables a DaisyUI 5 theme defines.
var DaisyRoles = []string{"base-100", "base-200", "base-300", "base-content",
	"primary", "primary-content", "secondary", "secondary-content", "accent", "accent-content",
	"neutral", "neutral-content", "info", "info-content", "success", "success-content",
	"warning", "warning-content", "error", "error-content"}

// DaisyShape are the non-colour variables, in DaisyUI's order.
var DaisyShape = []string{"radius-selector", "radius-field", "radius-box", "size-selector", "size-field", "border", "depth", "noise"}

// DaisyTheme is one theme's DaisyUI variables, in order.
type DaisyTheme struct {
	Theme *brand.Theme
	Vars  []brand.Decl
}

// DaisyVars resolves $extensions["com.mapleset.daisyui"] for one theme.
func DaisyVars(th *brand.Theme, format string) (*DaisyTheme, error) {
	ext := th.Tokens.Extensions.Object(brand.ExtDaisyUI)
	if ext == nil {
		return nil, fmt.Errorf("theme %s: the tokens have no $extensions[%q]", th.Name, brand.ExtDaisyUI)
	}
	dt := &DaisyTheme{Theme: th}
	colors := ext.Object("colors")
	for _, role := range DaisyRoles {
		v, ok := colors.Get(role)
		if !ok {
			return nil, fmt.Errorf("theme %s: DaisyUI colour %s isn't mapped", th.Name, role)
		}
		s, err := daisyValue(th, v, "color", format)
		if err != nil {
			return nil, fmt.Errorf("theme %s: DaisyUI %s: %w", th.Name, role, err)
		}
		dt.Vars = append(dt.Vars, brand.Decl{Name: "color-" + role, Value: s})
	}
	for _, k := range colors.Keys {
		if !slices.Contains(DaisyRoles, k) {
			return nil, fmt.Errorf("theme %s: %s isn't a DaisyUI colour", th.Name, k)
		}
	}
	for _, k := range DaisyShape {
		v, ok := ext.Get(k)
		if !ok {
			return nil, fmt.Errorf("theme %s: DaisyUI %s isn't set", th.Name, k)
		}
		s, err := daisyValue(th, v, "dimension", format)
		if err != nil {
			return nil, fmt.Errorf("theme %s: DaisyUI %s: %w", th.Name, k, err)
		}
		dt.Vars = append(dt.Vars, brand.Decl{Name: k, Value: s})
	}
	for _, k := range ext.Keys {
		if k != "colors" && !slices.Contains(DaisyShape, k) {
			return nil, fmt.Errorf("theme %s: unknown DaisyUI setting %s", th.Name, k)
		}
	}
	return dt, nil
}

// TokenRef resolves a "{a.b}" reference against a theme's tokens.
func TokenRef(th *brand.Theme, s string) (*dtcg.Token, bool) {
	if !strings.HasPrefix(s, "{") || !strings.HasSuffix(s, "}") {
		return nil, false
	}
	t := th.Tokens.Get(s[1 : len(s)-1])
	return t, t != nil
}

func daisyValue(th *brand.Theme, v any, want, format string) (string, error) {
	switch x := v.(type) {
	case float64:
		return brand.Num(x), nil
	case string:
		if strings.HasPrefix(x, "{") {
			t, ok := TokenRef(th, x)
			if !ok {
				return "", fmt.Errorf("%s isn't a token", x)
			}
			if want == "color" && t.Type != "color" {
				return "", fmt.Errorf("%s is a %s, not a color", x, t.Type)
			}
			ds, err := brand.Decls(t, format)
			if err != nil {
				return "", err
			}
			if len(ds) != 1 {
				return "", fmt.Errorf("%s isn't a single value", x)
			}
			return ds[0].Value, nil
		}
		if want == "color" {
			return "", fmt.Errorf("%q: map DaisyUI colours to colour tokens", x)
		}
		return x, nil
	}
	return "", fmt.Errorf("unsupported value %v", v)
}

// DaisyThemes writes the plain form: [data-theme] blocks for a project
// that loads a prebuilt daisyui.css.
func DaisyThemes(b *brand.Brand, format string) ([]byte, error) {
	var w bytes.Buffer
	fmt.Fprintf(&w, "/* %s DaisyUI themes for a prebuilt daisyui.css: load it, then this file. %s */\n", b.Config.Name, generatedBy(b))
	for _, th := range b.Themes {
		dt, err := DaisyVars(th, format)
		if err != nil {
			return nil, err
		}
		sel := fmt.Sprintf(`[data-theme="%s"]`, th.Config.DaisyUI)
		if th.Config.Default {
			sel += ", :root"
		}
		fmt.Fprintf(&w, "\n%s {\n  color-scheme: %s;\n", sel, th.Config.ColorScheme)
		for _, d := range dt.Vars {
			writeDecl(&w, d)
		}
		w.WriteString("}\n")
		if th.Config.PrefersDark && !th.Config.Default {
			fmt.Fprintf(&w, "\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme]) {\n    color-scheme: %s;\n", th.Config.ColorScheme)
			for _, d := range dt.Vars {
				fmt.Fprintf(&w, "    --%s: %s;\n", d.Name, d.Value)
			}
			w.WriteString("  }\n}\n")
		}
	}
	return w.Bytes(), nil
}

// DaisyPlugin writes the @plugin form for a Tailwind 4 build with vendored
// daisyui.js / daisyui-theme.js, plus an @theme block that resets
// Tailwind's default palette (and shadows, when the brand bans them) so
// only brand values exist as utilities.
func DaisyPlugin(b *brand.Brand, format string) ([]byte, error) {
	var w bytes.Buffer
	fmt.Fprintf(&w, "/* %s DaisyUI themes for Tailwind 4 with vendored daisyUI. Import after @import \"tailwindcss\". %s */\n", b.Config.Name, generatedBy(b))
	c := b.Config.DaisyUI
	if c.Plugin != "-" {
		fmt.Fprintf(&w, "\n@plugin %q {\n  themes: false;\n}\n", c.Plugin)
	}
	for _, th := range b.Themes {
		dt, err := DaisyVars(th, format)
		if err != nil {
			return nil, err
		}
		fmt.Fprintf(&w, "\n@plugin %q {\n  name: %q;\n  default: %t;\n  prefersdark: %t;\n  color-scheme: %s;\n",
			c.ThemePlugin, th.Config.DaisyUI, th.Config.Default, th.Config.PrefersDark, th.Config.ColorScheme)
		for _, d := range dt.Vars {
			writeDecl(&w, d)
		}
		w.WriteString("}\n")
	}
	rules, err := b.Default().Rules()
	if err != nil {
		return nil, err
	}
	w.WriteString("\n@theme {\n")
	if !c.KeepPalette {
		w.WriteString("  --color-*: initial;\n  --color-transparent: transparent;\n  --color-current: currentColor;\n")
	}
	if len(rules.Fonts) > 0 {
		w.WriteString("  --font-*: initial;\n")
		roles := make([]string, 0, len(rules.Fonts))
		for r := range rules.Fonts {
			roles = append(roles, r)
		}
		sort.Strings(roles)
		for _, r := range roles {
			t := b.Default().Tokens.Get(rules.Fonts[r])
			if t == nil || t.Type != "fontFamily" {
				return nil, fmt.Errorf("font role %s: %s isn't a fontFamily token", r, rules.Fonts[r])
			}
			fmt.Fprintf(&w, "  --font-%s: %s;\n", r, brand.FontFamilyCSS(t.Value))
		}
	}
	if rules.Shadows == "none" {
		w.WriteString("  --shadow-*: initial;\n  --inset-shadow-*: initial;\n  --drop-shadow-*: initial;\n  --text-shadow-*: initial;\n")
	}
	if len(rules.Radius) > 0 {
		// DaisyUI's rounded-selector, rounded-field and rounded-box stay.
		w.WriteString("  --radius-*: initial;\n")
	}
	w.WriteString("}\n")
	return w.Bytes(), nil
}

// LintConfig writes lint.json.
func LintConfig(b *brand.Brand) ([]byte, error) {
	rules, err := b.Default().Rules()
	if err != nil {
		return nil, err
	}
	l := lint.Config{Version: 1, Brand: b.Config.Name, Shadows: rules.Shadows, OpacityMin: rules.OpacityMin}
	if l.OpacityMin == 0 {
		l.OpacityMin = 70
	}
	if rules.Icons != nil {
		l.IconSet, l.IconName = rules.Icons.Set, rules.Icons.Prefix
	}
	fonts := map[string]bool{}
	for _, th := range b.Themes {
		for _, t := range th.Tokens.List {
			switch t.Type {
			case "fontFamily":
				for _, f := range brand.FontFamilies(t.Value) {
					fonts[f] = true
				}
			case "typography":
				for _, f := range brand.FontFamilies(t.Value.(*dtcg.Object).Values["fontFamily"]) {
					fonts[f] = true
				}
			}
		}
	}
	for f := range fonts {
		l.Fonts = append(l.Fonts, f)
	}
	sort.Strings(l.Fonts)
	out, err := json.MarshalIndent(l, "", "  ")
	if err != nil {
		return nil, err
	}
	return append(out, '\n'), nil
}
